const initial = {source:'WAIT', door:'UNKNOWN', lock:'UNKNOWN', motion:false, mode:'NORMAL', alarm:false, reason:'', buzzer:false, relay:false, failedRFID:0, failedPIN:0, lastAccess:'—', count:0, updatedAt:'', events:[]};
let s=flow.get('smartlab_state') || initial;
const p=(typeof msg.payload==='string') ? (()=>{try{return JSON.parse(msg.payload)}catch(e){return null}})() : msg.payload;
if (!p || typeof p!=='object') return null;
if (msg.topic==='smartlab/security/telemetry') {
 const allowed=['door','lock','motion','mode','alarm','reason','buzzer','relay','failedRFID','failedPIN','lastAccess'];
 for(const k of allowed) if(Object.prototype.hasOwnProperty.call(p,k))s[k]=p[k];
 s.source='MQTT';s.count=(s.count||0)+1;s.updatedAt=new Date().toLocaleTimeString('id-ID');
} else if(msg.topic==='smartlab/security/event') {
 const ev={time:new Date().toLocaleTimeString('id-ID'),type:String(p.type||'EVENT').slice(0,40),detail:String(p.detail||'').slice(0,200)};
 s.events=[ev,...(s.events||[])].slice(0,30);s.source='MQTT';s.updatedAt=ev.time;
} else if(msg.topic==='DEMO') {
 s={...s,...p,source:'DEMO',count:(s.count||0)+1,updatedAt:new Date().toLocaleTimeString('id-ID')};
 if(p.demoEvent)s.events=[{time:s.updatedAt,type:p.demoEvent,detail:'Simulasi dashboard (bukan perangkat nyata)'},...(s.events||[])].slice(0,30);
} else {return null}
flow.set('smartlab_state',s);
return {payload:{kind:'state',state:s}};

const c=String(msg.payload||'').toUpperCase().trim();
// Hanya kendali non-kritis; tanpa UNLOCK/RESET lewat dashboard.
if (!['NORMAL','AFTERHOURS','SILENCE'].includes(c))return null;
return {topic:'smartlab/security/cmd',payload:c,qos:'0',retain:'false'};

const command = String(msg.payload)
    .trim()
    .toUpperCase();

let state = flow.get("smartlab_sim_state") || {
    door: "CLOSED",
    lock: "LOCKED",
    pir: "CLEAR",
    alarm: false,
    buzzer: false,
    relay: false,
    mode: "NORMAL",
    rfid_failed: 0,
    pin_failed: 0
};

switch (command) {
    case "AFTERHOURS":
        state.mode = "AFTERHOURS";
        break;

    case "NORMAL":
        state.mode = "NORMAL";
        break;

    case "SILENCE":
        state.buzzer = false;
        break;

    default:
        node.warn("Unknown command: " + command);
        return null;
}

flow.set("smartlab_sim_state", state);

msg.topic = "smartlab/security/telemetry";
msg.payload = JSON.stringify(state);

node.status({
    fill: "green",
    shape: "dot",
    text: state.mode
});

return msg;

// Smart Lab Security Simulation Engine V2
// Node-RED Function node, 2 outputs:
//   Output 1 -> MQTT Out, smartlab/security/telemetry
//   Output 2 -> MQTT Out, smartlab/security/event
// INPUT: MQTT cmd, MQTT sim/cmd, or Inject TICK every 2 seconds.
// This simulator never operates a physical lock.

const TELE = 'smartlab/security/telemetry';
const EVENT = 'smartlab/security/event';
const now = Date.now();
const topic = String(msg.topic || '');
const raw = typeof msg.payload === 'string' ? msg.payload : String(msg.payload ?? '');
const command = raw.trim().toUpperCase();

let s = context.get('state') || {
    door: 'CLOSED', lock: 'LOCKED', motion: false,
    alarm: false, reason: '', buzzer: false, relay: false,
    mode: 'NORMAL', failedRFID: 0, failedPIN: 0,
    lastAccess: '—', unlockedAt: 0, openedAfterUnlock: false,
    buzzerSilenced: false
};
let events = [];
let changed = false;

function record(type, detail) {
    events.push({topic: EVENT, payload: JSON.stringify({
        type, detail, source: 'SIMULATOR', timestamp: new Date(now).toISOString()
    }), qos: '0', retain: 'false'});
    changed = true;
}
function alarm(reason) {
    if (s.alarm) return;
    s.alarm = true;
    s.reason = reason;
    s.buzzerSilenced = false;
    s.buzzer = true;
    s.relay = true;
    record('ALARM_TRIGGERED', reason);
}
function unlock(method) {
    if (s.alarm || s.door === 'OPEN') {
        record('ACCESS_BLOCKED', 'Alarm aktif atau pintu terbuka');
        return;
    }
    s.lock = 'UNLOCKED';
    s.unlockedAt = now;
    s.openedAfterUnlock = false;
    s.lastAccess = method;
    s.failedRFID = 0;
    s.failedPIN = 0;
    record('ACCESS_GRANTED', 'Autentikasi melalui ' + method);
}
function lock(reason) {
    if (s.door === 'OPEN') {
        record('LOCK_BLOCKED', 'Sensor menunjukkan pintu terbuka');
        return;
    }
    if (s.lock !== 'LOCKED') {
        s.lock = 'LOCKED';
        s.unlockedAt = 0;
        s.openedAfterUnlock = false;
        record('DOOR_LOCKED', reason);
    }
}

const operational = ['NORMAL','AFTERHOURS','SILENCE'];
const simulated = ['RFID_VALID','RFID_INVALID','PIN_VALID','PIN_INVALID',
  'DOOR_OPEN','DOOR_CLOSED','MOTION_ON','MOTION_OFF','LOCK','RESET','INIT'];
const isTick = command === 'TICK';
const fromDashboard = topic === 'smartlab/security/cmd';
const fromSimulator = topic === 'smartlab/security/sim/cmd';

if (!isTick && !(fromDashboard && operational.includes(command)) &&
    !(fromSimulator && [...operational, ...simulated].includes(command))) {
    node.warn('Perintah diabaikan dari topic ' + topic + ': ' + command);
    return null;
}

if (isTick) {
    if (s.lock === 'UNLOCKED' && s.door === 'CLOSED' &&
        !s.openedAfterUnlock && now - s.unlockedAt >= 10000) {
        lock('Auto-lock setelah 10 detik');
    }
} else {
    switch (command) {
        case 'NORMAL':
            s.mode = 'NORMAL';
            record('MODE_CHANGE', 'Mode NORMAL');
            break;
        case 'AFTERHOURS':
            s.mode = 'AFTERHOURS';
            record('MODE_CHANGE', 'Mode AFTERHOURS');
            if (s.motion && s.lock === 'LOCKED') alarm('INTRUSI_PIR');
            break;
        case 'SILENCE':
            if (s.alarm) {
                s.buzzerSilenced = true;
                s.buzzer = false;
                record('ALARM_SILENCED', 'Buzzer dimatikan, alarm tetap aktif');
            }
            break;
        case 'RFID_VALID': unlock('RFID'); break;
        case 'PIN_VALID': unlock('KEYPAD'); break;
        case 'RFID_INVALID':
            if (!s.alarm && s.lock === 'LOCKED') {
                s.failedRFID++;
                record('RFID_DENIED', 'Kartu tidak terdaftar (' + s.failedRFID + '/3)');
                if (s.failedRFID >= 3) alarm('RFID_GAGAL_3X');
            }
            break;
        case 'PIN_INVALID':
            if (!s.alarm && s.lock === 'LOCKED') {
                s.failedPIN++;
                record('PIN_DENIED', 'PIN salah (' + s.failedPIN + '/3)');
                if (s.failedPIN >= 3) alarm('PIN_GAGAL_3X');
            }
            break;
        case 'DOOR_OPEN':
            if (s.door !== 'OPEN') {
                s.door = 'OPEN';
                record('DOOR_OPEN', 'Pintu terbuka');
                if (s.lock === 'LOCKED') alarm('PINTU_DIBUKA_PAKSA');
                else s.openedAfterUnlock = true;
            }
            break;
        case 'DOOR_CLOSED':
            if (s.door !== 'CLOSED') {
                s.door = 'CLOSED';
                record('DOOR_CLOSED', 'Pintu tertutup');
                if (s.lock === 'UNLOCKED' && s.openedAfterUnlock) {
                    lock('Otomatis setelah pintu ditutup');
                }
            }
            break;
        case 'MOTION_ON':
            if (!s.motion) {
                s.motion = true;
                record('MOTION_DETECTED', 'Gerakan PIR');
                if (s.mode === 'AFTERHOURS' && s.lock === 'LOCKED') alarm('INTRUSI_PIR');
            }
            break;
        case 'MOTION_OFF':
            if (s.motion) {
                s.motion = false;
                record('MOTION_CLEARED', 'Gerakan berhenti');
            }
            break;
        case 'LOCK': lock('Perintah simulasi'); break;
        case 'RESET':
            if (s.door === 'OPEN' || (s.mode === 'AFTERHOURS' && s.motion)) {
                record('RESET_DENIED', 'Tutup pintu dan pastikan tidak ada intrusi');
            } else {
                s.alarm = false;
                s.reason = '';
                s.buzzer = false;
                s.relay = false;
                s.buzzerSilenced = false;
                s.failedRFID = 0;
                s.failedPIN = 0;
                s.lock = 'LOCKED';
                s.unlockedAt = 0;
                s.openedAfterUnlock = false;
                record('ALARM_RESET', 'Reset lokal simulator berhasil');
            }
            break;
        case 'INIT':
            s = {door:'CLOSED',lock:'LOCKED',motion:false,alarm:false,
                 reason:'',buzzer:false,relay:false,mode:'NORMAL',
                 failedRFID:0,failedPIN:0,lastAccess:'—',
                 unlockedAt:0,openedAfterUnlock:false,buzzerSilenced:false};
            record('SIM_INIT', 'Simulator diinisialisasi ulang');
            break;
    }
}
context.set('state', s);
node.status({fill:s.alarm?'red':'green',shape:'dot',
    text:s.alarm?'ALARM '+s.reason:s.mode+' '+s.door+'/'+s.lock});

// Format ini cocok dengan State + event log pada dashboard V1.
const telemetry = {
    topic: TELE, qos: '0', retain: 'false',
    payload: JSON.stringify({
        door:s.door, lock:s.lock, motion:s.motion, mode:s.mode,
        alarm:s.alarm, reason:s.reason, buzzer:s.buzzer, relay:s.relay,
        failedRFID:s.failedRFID, failedPIN:s.failedPIN,
        lastAccess:s.lastAccess
    })
};
return [telemetry, events.length ? events : null];

// Hanya menerima perintah dari panel simulasi V3.
// Topic khusus SIMULASI; tidak boleh digunakan untuk membuka pintu fisik.
const allowed = new Set([
  'RFID_VALID','RFID_INVALID','PIN_VALID','PIN_INVALID',
  'DOOR_OPEN','DOOR_CLOSED','MOTION_ON','MOTION_OFF',
  'LOCK','SILENCE','RESET','INIT'
]);
if (msg.topic !== 'smartlab/security/sim/cmd') return null;
const command = String(msg.payload || '').trim().toUpperCase();
if (!allowed.has(command)) {
  node.warn('Perintah simulasi tidak dikenal: ' + command);
  return null;
}
return {topic:'smartlab/security/sim/cmd',payload:command,qos:'0',retain:'false'};

 // V4 Tahap 10 — Hardware State Processor
 // Memproses telemetry ESP32-S3 fisik.
 // Tidak mencampurkan data simulator V3 (MQTT 1883)
 // dengan hardware V4 (MQTT 1884).

const TOPIC = 'smartlab/security/hardware/telemetry';

// Hanya proses telemetry hardware.
if (msg.topic !== TOPIC) return null;

// Parsing JSON
let p;

try {
    p = (typeof msg.payload === 'string')
        ? JSON.parse(msg.payload)
        : msg.payload;
} catch (e) {
    node.warn('Telemetry JSON invalid');
    return null;
}

// Validasi payload
if (!p || typeof p !== 'object' || Array.isArray(p)) {
    return null;
}

const enumOK = (v, arr) => arr.includes(v);

// Validasi parameter wajib
if (
    !enumOK(p.door, ['OPEN', 'CLOSED']) ||
    !enumOK(p.lock, ['LOCKED', 'UNLOCKED']) ||
    !enumOK(p.mode, ['NORMAL', 'AFTERHOURS']) ||
    typeof p.motion !== 'boolean' ||
    typeof p.alarm !== 'boolean'
) {
    node.warn('Hardware telemetry required fields invalid');
    return null;
}

// Membatasi nilai counter
const boundedInt = v =>
    Number.isInteger(v)
        ? Math.max(0, Math.min(999, v))
        : 0;

// Menyusun state hardware
const state = {
    source: 'HARDWARE',

    device: String(
        p.device || 'ESP32-S3'
    ).slice(0, 32),

    door: p.door,

    // Status perintah servo,
    // bukan bukti penguncian mekanis.
    lock: p.lock,

    lock_verified: p.lock_verified === true,

    motion: p.motion,

    alarm: p.alarm,

    mode: p.mode,

    buzzer: typeof p.buzzer === 'boolean'
        ? p.buzzer
        : null,

    relay: typeof p.relay === 'boolean'
        ? p.relay
        : null,

    buzzer_silenced: p.buzzer_silenced === true,

    pir_ready: p.pir_ready === true,

    failedRFID: boundedInt(p.failedRFID),

    failedPIN: boundedInt(p.failedPIN),

    lastAccess: String(
        p.lastAccess || 'NONE'
    ).slice(0, 20),

    alarm_reason: String(
        p.alarm_reason || ''
    ).slice(0, 80),

    lastUpdate: new Date().toISOString()
};

// Simpan state hardware secara terpisah.
flow.set('smartlab_v4_hardware_state', state);

// Perbarui status Function Node
node.status({
    fill: state.alarm ? 'red' : 'green',
    shape: 'dot',
    text: state.door + '/' + state.lock +
        (state.alarm ? ' ALARM' : '')
});

// Kirim data menuju Debug dan Dashboard V4.
return {
    topic: 'smartlab/security/hardware/state',
    payload: state
};

const TOPIC = "smartlab/security/hardware/event";

if (msg.topic !== TOPIC) {
    return null;
}

let data;

try {
    data = typeof msg.payload === "string"
        ? JSON.parse(msg.payload)
        : msg.payload;
} catch (err) {
    node.warn("Hardware event JSON tidak valid");
    return null;
}

if (!data || typeof data !== "object" ||
    data.source !== "HARDWARE" ||
    typeof data.type !== "string") {
    return null;
}

const event = {
    time: new Date().toLocaleTimeString("id-ID"),
    type: data.type.slice(0, 40),
    detail: String(data.detail || "").slice(0, 100),
    source: "HARDWARE"
};

let events = flow.get("smartlab_v4_events") || [];

events.unshift(event);
events = events.slice(0, 30);

flow.set("smartlab_v4_events", events);

node.status({
    fill: event.type.includes("DENIED") ||
          event.type.includes("ALARM")
          ? "red" : "green",
    shape: "dot",
    text: event.type
});

return {
    topic: "smartlab/security/hardware/eventlog",
    payload: events
};
